<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import AppLayout from '../../components/layout/AppLayout.vue'
import BaseCard from '../../components/ui/BaseCard.vue'
import ListToolbar from '../../components/ui/ListToolbar.vue'
import PaginationControls from '../../components/ui/PaginationControls.vue'
import { api } from '../../services/api'
import { userError } from '../../utils/errors'
const data = ref<{ previsions: Array<Record<string, unknown>>; recommandations: Array<Record<string, unknown>>; anomalies: Array<Record<string, unknown>>; limites: string } | null>(null); const loading = ref(true); const error = ref(''); const search = ref(''); const sortOrder = ref<'asc' | 'desc'>('asc'); const pageSize = 20; const previsionPage = ref(1); const recommandationPage = ref(1); const anomaliePage = ref(1)
function filteredRows(rows: Array<Record<string, unknown>>) { const term = search.value.trim().toLowerCase(); return [...rows].filter((row) => !term || Object.values(row).some((value) => String(value ?? '').toLowerCase().includes(term))).sort((left, right) => { const a = String(left.libelle ?? left.date ?? ''); const b = String(right.libelle ?? right.date ?? ''); const comparison = a.localeCompare(b, 'fr', { numeric: true, sensitivity: 'base' }); return sortOrder.value === 'asc' ? comparison : -comparison }) }
const filteredPrevisions = computed(() => filteredRows(data.value?.previsions || [])); const filteredRecommandations = computed(() => filteredRows(data.value?.recommandations || [])); const filteredAnomalies = computed(() => filteredRows(data.value?.anomalies || []))
const previsionPages = computed(() => Math.max(1, Math.ceil(filteredPrevisions.value.length / pageSize))); const recommandationPages = computed(() => Math.max(1, Math.ceil(filteredRecommandations.value.length / pageSize))); const anomaliePages = computed(() => Math.max(1, Math.ceil(filteredAnomalies.value.length / pageSize)))
const visiblePrevisions = computed(() => filteredPrevisions.value.slice((previsionPage.value - 1) * pageSize, previsionPage.value * pageSize)); const visibleRecommandations = computed(() => filteredRecommandations.value.slice((recommandationPage.value - 1) * pageSize, recommandationPage.value * pageSize)); const visibleAnomalies = computed(() => filteredAnomalies.value.slice((anomaliePage.value - 1) * pageSize, anomaliePage.value * pageSize))
function resetLists() { previsionPage.value = 1; recommandationPage.value = 1; anomaliePage.value = 1 }
function toggleSort() { sortOrder.value = sortOrder.value === 'asc' ? 'desc' : 'asc'; resetLists() }
watch([search, sortOrder], resetLists)
async function load() { try { data.value = (await api.get('/aide-decision')).data } catch (value: unknown) { error.value = userError(value, 'Impossible de charger l’aide à la décision.', 'INSIGHTS_ERROR') } finally { loading.value = false } }
onMounted(load)
</script>
<template><AppLayout><template #title>Aide à la décision</template><section class="page-intro"><div><p class="eyebrow">ANALYSE EXPLICABLE</p><h2>Prévisions et recommandations</h2><p>Résultats calculés à partir des 90 derniers jours et soumis à validation.</p></div></section><p v-if="loading" class="status-msg">Calcul en cours…</p><p v-else-if="error" class="error-banner" role="alert">{{ error }}</p><template v-else-if="data"><ListToolbar v-model="search" :loading="loading" placeholder="Rechercher dans les analyses" :sort-label="sortOrder === 'asc' ? 'Tri A → Z' : 'Tri Z → A'" @search="resetLists" @sort="toggleSort" /><section class="content-grid"><BaseCard><div class="card-heading"><div><h2>Prévisions ({{ filteredPrevisions.length }})</h2><p>Demande estimée par itinéraire.</p></div></div><div v-if="visiblePrevisions.length"><div v-for="row in visiblePrevisions" :key="String(row.id_itineraire)" class="insight-row"><strong>{{ row.libelle }}</strong><span>{{ row.passagers_7_jours }} passagers/jour · {{ row.remplissage_7_jours }}% de remplissage</span><small>{{ row.observations }} observation(s) · {{ row.methode }}</small></div></div><div v-else class="empty-state">Aucune prévision ne correspond à la recherche.</div><PaginationControls :page="previsionPage" :pages="previsionPages" :total="filteredPrevisions.length" item-label="prévision(s)" @change="previsionPage = $event" /></BaseCard><BaseCard><div class="card-heading"><div><h2>Recommandations ({{ filteredRecommandations.length }})</h2><p>Propositions à valider par l’équipe.</p></div></div><div v-if="visibleRecommandations.length"><div v-for="row in visibleRecommandations" :key="String(row.id_itineraire)" class="insight-row"><strong>{{ row.libelle }}</strong><span>{{ row.departs_recommandes }} départ(s) recommandé(s)</span><small>{{ row.raison }}</small></div></div><div v-else class="empty-state">Aucune recommandation ne correspond à la recherche.</div><PaginationControls :page="recommandationPage" :pages="recommandationPages" :total="filteredRecommandations.length" item-label="recommandation(s)" @change="recommandationPage = $event" /></BaseCard><BaseCard><div class="card-heading"><div><h2>Anomalies à vérifier ({{ filteredAnomalies.length }})</h2><p>Éléments nécessitant une vérification humaine.</p></div></div><div v-if="visibleAnomalies.length"><div v-for="row in visibleAnomalies" :key="`${row.id_itineraire}-${row.date}`" class="insight-row"><strong>{{ row.libelle }}</strong><span>{{ row.date }} · {{ row.valeur }} passagers · z-score {{ row.z_score }}</span><small>{{ row.type }}</small></div></div><div v-else class="empty-state">Aucune anomalie détectée.</div><PaginationControls :page="anomaliePage" :pages="anomaliePages" :total="filteredAnomalies.length" item-label="anomalie(s)" @change="anomaliePage = $event" /><p class="muted">{{ data.limites }}</p></BaseCard></section></template></AppLayout></template>
<style scoped>.content-grid { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:1rem; }.content-grid :deep(.base-card) { padding:1.25rem; }.insight-row { display:grid; gap:.25rem; padding:.75rem 0; border-bottom:1px solid #e2e8f0; color:#475569; }.insight-row strong { color:#0f172a; }.insight-row small,.muted { color:#64748b; }@media (max-width: 1100px) { .content-grid { grid-template-columns:1fr; } }</style>
